sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({ api, event, helpers, imports }) {
    // Log the entire event object for debugging
    const selectedTab = event.payload.selectedTab;

    // Extract and log the value after `=` for any key-value pair like `set=api`
    if (selectedTab && typeof selectedTab === "string") {
        const keyValuePair = selectedTab.split("=");
        if (keyValuePair.length === 2) {
            const key = keyValuePair[0].trim(); // Extract the key (e.g., "set")
            const value = keyValuePair[1].trim(); // Extract the value (e.g., "api")

            console.log("Key:", key);
            console.log("Value:", value);
            api.setState('selectedIntegration',value)
            console.log(api.state.selectedIntegration);

        } else {
            console.log("Invalid key-value pair format:", selectedTab);
        }
    } else {
        console.log("Invalid selectedTab format:", selectedTab);
    }
}
